    and not fa.enclosingClass contains [FunctionCall: function.name == "__getitem__" and
        arguments contains fa]
    and fa in [AssignmentStatement:
        lhs.location is [Location l:
            l.transitiveBase === fa.transitiveBase
        ] and rhs.constantValue is [Null:]
    ] and fa.field is [Field f:]*

