FunctionCall fc: fc.possibleTargets contains [Function f:
        name == "__init__"
        and enclosingClass.name matches "oslo_config\.cfg\.(Str|Float|Bool|Int|List|Dict)?Opt"
    ]
    and (
        namedParameters contains [NamedParameter p:
            name == "secret"
            /*if secret=False then the password, for example, will be printed in clear*/
            and p.expression is [VariableAccess va: variable.name == "False"]
            /*Check if "secret" is assigned a variable of "False" value, example: secret=sec, where sec=False*/
            or p.expression is [VariableAccess va0: va0 in [Statement sa: sa contains [AssignmentStatement:
                rhs is [VariableAccess va1: va1.variable.name == "False"]
                and lhs is [ VariableAccess va2: va2 is va0 ]
            ]]]
        ]
        /* Check if "secret" parameter is not in namedParameters as the default value is "False"*/
        or not namedParameters contains [NamedParameter p1: name == "secret" ]
    )
    and arguments[1] is [Expression:
        constantValue matches  "(?i)^ssn.*|.*ssn$|.social.*security.*|.*creditcard.*|.*card(num|no).*|.*cvv.*|.*pin$"
    ]

FunctionCall fc:
    fc.function is [Function:
        name == "as_view"
        and enclosingClass.supers contains [Class:
            name == "flask.views.View"
        ]
    ]
    and fc.environment is [FieldAccess:
        accessInstance is [FieldAccess:
            accessInstance is [VariableAccess:
                variable.type is [Type:
                    name == "flask_graphql.graphqlview.GraphQLView"
                ]
            ]
        ]
    ]
    and fc.namedParameters contains [NamedParameter:
        name == "graphiql"
        and (
          expression is [VariableAccess: variable.name == "True"]*
          or expression is [BooleanLiteral: value is true]*
        )
    ]

FunctionCall fc:
    fc.function is [Function:
        name == "as_view"
        and enclosingClass.supers contains [Class:
            name == "flask.views.View"
        ]
    ]
    and fc.environment is [FieldAccess:
        accessInstance is [FieldAccess:
            accessInstance is [VariableAccess:
                variable.type is [Type:
                    name == "flask_graphql.graphqlview.GraphQLView"
                ]
            ]
        ]
    ]
    and not fc.namedParameters contains [NamedParameter:
        name == "middleware"
    ]

FunctionCall fc: possibleTargets contains [Function:
        name == "__getitem__"
    ]
    and arguments[0] is [FieldAccess fa:
        fa.field.name == "META"
        /* Commenting out until TI does a better job
            and fa.instance.possibleTypes contains [Type:
            definition.supers contains [Class:
                name matches "django\.http(\.request)?\.HttpRequest"
            ]
        ] */
    ] and arguments[1].constantValue matches "(?i)host"

FunctionCall fc: possibleTargets contains [Function f:
        name == "pbkdf2"
        and namespace.name == "django.utils.crypto"
    ]
    and namedParameters contains [NamedParameter:
        name == "dklen"
        and expression.constantValue is [Number n:
            n <  128 and n != 0
        ]
    ]

Statement s: s contains [AssignmentStatement:
        lhs is [VariableAccess:
            variable.name == "EMAIL_HOST"
            and variable.namespace.name matches ".*settings.*"
        ]*
    ] and (not s contains [AssignmentStatement:
        lhs is [VariableAccess:
            variable.name == "EMAIL_USE_TLS"
            and variable.namespace.name matches ".*settings.*"
        ]*
        and rhs is [VariableAccess:
            variable.name == "True"
        ]*
    ] or s contains [AssignmentStatement:
        lhs is [VariableAccess:
            variable.name == "EMAIL_USE_TLS"
            and variable.namespace.name matches ".*settings.*"
        ]*
        and rhs is [VariableAccess:
            variable.name == "False"
        ]*
    ])

Statement s: s contains [AssignmentStatement:
        lhs is [VariableAccess:
            variable.name matches "MIDDLEWARE(_CLASSES)?"
            and variable.namespace.name matches ".*settings.*"
        ]*
        and rhs is [FunctionCall:
            possibleTargets contains [Function: name matches "~python~(tuple|list)"]
            and arguments contains [Expression:
                constantValue == "django.middleware.csrf.CsrfViewMiddleware"
            ]
        ]*
    ] and s contains [AssignmentStatement:
        lhs is [VariableAccess:
            variable.name matches "MIDDLEWARE(_CLASSES)?"
            and variable.namespace.name matches ".*settings.*"
        ]*
        and rhs is [FunctionCall:
            possibleTargets contains [Function: name matches "~python~(tuple|list)"]
            and arguments contains [Expression:
                constantValue == "django.middleware.gzip.GZipMiddleware"
            ]
        ]*
    ]

Statement s: s contains [AssignmentStatement:
        lhs is [VariableAccess:
            variable.name == "CACHE_BACKEND"
            and variable.namespace.name matches ".*settings.*"
        ]
        and rhs.constantValue matches ".*memcached.*"
    ] or s contains [AssignmentStatement:
        lhs is [VariableAccess:
            variable.name == "CACHES"
            and variable.namespace.name matches ".*settings.*"
        ]
        and rhs is [FunctionCall:
            possibleTargets contains [Function: name == "~python~dict"]
