CharacterizationRule.Script:
/* String search through generated proto files for generated namespace names. (need a better dynamic way of getting namespace info, but as of now this is the only way) */
gRPC_gen_ns = find_grpc_namespaces();

var repl = "";

/* create predicate matches on found namespaces */
for(var i = 0; i < gRPC_gen_ns.length - 1; i++){

    repl += "(fpc.closureExpression is [FieldAccess: name matches \"" + String(gRPC_gen_ns[i]) + ".*\"]) or ";

}


/*if we found namespaces, add in the last one without the or. If we didn't find any, add a nonsense value that won't match */
if(gRPC_gen_ns.length > 0){
    repl += "(fpc.closureExpression is [FieldAccess: name matches \"" + String(gRPC_gen_ns[gRPC_gen_ns.length - 1]) + ".*\"])";
    repl = 'FunctionPointerCall fpc: fpc.instance is [Expression ex:] and ' + repl
    rule.StructuralMatch = String(repl);
}
else{
    delete rule;
}

