CharacterizationRule.StructuralMatch:
FunctionCall fc: fc.possibleTargets contains [Function f: 
    name matches "get_(body|json)"
]
and enclosingFunction is [Function:
    /* Lambda Function entry point */
    not labels contains "GCP_Func_Entry_Point"
    /* Lambda Function trigger type */
    and not labels contains "GCP_Func_http_trigger"
]
and instance is [ VariableAccess req:
req.variable.name matches "req(uest)?"]

FunctionPointerCall fpc: fpc.functionPointer is [FieldAccess fa:
    fa.instance is [FieldAccess fa2:
    fa2.field.name matches "get"
    and fa2.instance is [FieldAccess pa:
        pa.field.name matches "params" 
        and pa.instance is [VariableAccess req:
        req.variable.name matches "req(uest)?"
        ] 
      ]
    ]
] and fpc.arguments[1] is [Expression e: ]

AssignmentStatement as: rhs is [FieldAccess fa: fa.field.name matches "path|kind|version"
    and fa.instance is [VariableAccess va:  va.variable.name matches "(?i)partition(_?key)?" 
        ]
    ]                     
    and lhs is [Expression pa: ]

FunctionPointerCall fpc: fpc.functionPointer is [FieldAccess fa:
    fa.instance is [FieldAccess fa2:
    fa2.field.name matches "get"
    and fa2.instance is [FieldAccess pa:
        pa.field.name matches "params"
        and pa.instance is [VariableAccess req:
        req.variable.name matches "req(uest)?"
        ]
     ]
  ]
] and fpc.instance is [Expression r: ]

FunctionPointerCall fpc: fpc.functionPointer is [FieldAccess fa:
    fa.instance is [FieldAccess fa2:
    fa2.field.name matches "get"
    and fa2.instance is [FieldAccess pa:
        pa.field.name matches "params|headers" 
        and pa.instance is [VariableAccess req:
        req.variable.name matches "req(uest)?"
        ]
      ] 
    ]     
] 
and fpc.arguments[1] is [Expression e: constantValue matches "(?i)code|x-functions-key" ]
and
(
    enclosingFunction.labels contains "Python_Azure_Func_Key"
    or enclosingFunction reachedBy [Function:
        labels contains "Python_Azure_Func_Key"
    ]
)

CharacterizationRule.Script:
var azureBindings = getAzureFunctionBindings();
var newStructuralMatch = String(buildAzureFuncRulePredicate(azureBindings, "httpTrigger", "in"));
// alert(newStructuralMatch);

if (newStructuralMatch != "") {
    rule.StructuralMatch = newStructuralMatch;
}

