ControlflowRule.Definition:
state start enter;
state initialized : "statedesc.python.smtp.init";
state secured;
state error (error) : "statedesc.python.insecure.transportation";
var i;
var j;
enter -> initialized { $initSMTP(i, ...)}
initialized -> initialized { j = $enter(@i, ...) }
initialized -> secured { $configTLS(@i, ...) |  $configTLS(@j, ...)  }
initialized -> error { $sendMail(@i, ...) | $sendMail(@j, ...) }

CharacterizationRule.StructuralMatch:
Function f:
    f.name == "resolve"
    and f contains [FieldAccess fa:
        fa.field.name == "field_name"
        and fa.instance is [VariableAccess va:
            va.variable is f.parameters[3]
        ]
    ]
    and (f contains [IfStatement:
        expression is [Operation:
            (lhs is [FunctionCall:
                arguments contains [Expression: constantValue == "__schema"]
            ]
            or lhs is [Expression: constantValue == "__schema"])
        ]
    ]
    or f contains [IfStatement:
        expression is [Operation:
            (rhs is [FunctionCall:
                arguments contains [Expression: constantValue == "__schema"]
            ]
            or rhs is [Expression: constantValue == "__schema"])
        ]
    ])
    and (f contains [IfStatement:
        expression is [Operation:
            (lhs is [FunctionCall:
                arguments contains [Expression: constantValue == "__introspection"]
            ]
            or lhs is [Expression: constantValue == "__introspection"])
        ]
    ]
    or f contains [IfStatement:
        expression is [Operation:
            (rhs is [FunctionCall:
                arguments contains [Expression: constantValue == "__introspection"]
            ]
            or rhs is [Expression: constantValue == "__introspection"])
        ]
    ])
    and f.enclosingClass is [Class c:]

